def set_zeroes(g):
    m, n = len(g), len(g[0])
    row0 = any(g[0][c] == 0 for c in range(n))
    col0 = any(g[r][0] == 0 for r in range(m))
    for r in range(1, m):
        for c in range(1, n):
            if g[r][c] == 0:
                g[r][0] = 0
                g[0][c] = 0
    for r in range(1, m):
        for c in range(1, n):
            if g[r][0] == 0 or g[0][c] == 0:
                g[r][c] = 0
    if row0:
        for c in range(n):
            g[0][c] = 0
    if col0:
        for r in range(m):
            g[r][0] = 0
    return g

