def spread(g):
    m, n = len(g), len(g[0])
    for r in range(m):
        for c in range(n):
            lit = g[r][c] & 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < m and 0 <= cc < n and g[rr][cc] & 1:
                    lit = 1
            g[r][c] |= lit << 1
    for r in range(m):
        for c in range(n):
            g[r][c] >>= 1
    return g

