static final int[] DR = {1, -1, 0, 0}, DC = {0, 0, 1, -1};

static int[][] spread(int[][] g) {
    int m = g.length, n = g[0].length;
    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++) {
            int lit = g[r][c] & 1;
            for (int d = 0; d < 4; d++) {
                int rr = r + DR[d], cc = c + DC[d];
                if (rr >= 0 && rr < m && cc >= 0 && cc < n && (g[rr][cc] & 1) == 1) lit = 1;
            }
            g[r][c] |= lit << 1;
        }
    for (int r = 0; r < m; r++)
        for (int c = 0; c < n; c++) g[r][c] >>= 1;
    return g;
}

